import { total } from './total.js'

export const tests = [
  { input: [2,3], expected: 5 },
  { input: [-2,-3], expected: -5 },
  { input: [], expected: 0 },
  { input: ["invalid"], error: true },
  { input: [NaN], error: true },
  { input: [Infinity], error: true },
]

tests.forEach(({ input, expected, error }, index) => {
  if (error) {
    assert.throws(() => total(input), Error)
  } else {
    assert.equal(total(input), expected)
  }
})

